    kind: "product-design",
    title: page.name || "Product design",
    pageId: page.id,
    pageIndex: index,
    pageCount: basePages(doc).length,
    page: { id: page.id, name: page.name, frame: page.frame, elements: page.elements },
    revision: snapshot.revision
